#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double a=1,b=0;feclearexcept(FE_ALL_EXCEPT);(void)(a/b);return fetestexcept(FE_DIVBYZERO)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double z=0;feclearexcept(FE_ALL_EXCEPT);(void)(z/z);return fetestexcept(FE_INVALID)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double a=1,z=0;feclearexcept(FE_ALL_EXCEPT);(void)(a/z);int first=fetestexcept(FE_DIVBYZERO);feclearexcept(FE_ALL_EXCEPT);(void)(a/z);return first&&fetestexcept(FE_DIVBYZERO)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double a=1,b=0x1p-53;fesetround(FE_UPWARD);double up=a+b;fesetround(FE_DOWNWARD);double down=a+b;fesetround(FE_TONEAREST);return up==0x1.0000000000001p0&&down==1?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double a=1,b=0x1p-54;fesetround(FE_UPWARD);double up=a-b;fesetround(FE_DOWNWARD);double down=a-b;fesetround(FE_TONEAREST);return up==1&&down==0x1.fffffffffffffp-1?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double a=1,b=10;fesetround(FE_UPWARD);double up=a/b;fesetround(FE_DOWNWARD);double down=a/b;fesetround(FE_TONEAREST);return up>down?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double d=1+0x1p-24;fesetround(FE_UPWARD);float up=(float)d;fesetround(FE_DOWNWARD);float down=(float)d;fesetround(FE_TONEAREST);return up==0x1.000002p0f&&down==1?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){int n=16777217;fesetround(FE_UPWARD);float up=(float)n;fesetround(FE_DOWNWARD);float down=(float)n;fesetround(FE_TONEAREST);return up==16777218.0f&&down==16777216.0f?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){feclearexcept(FE_ALL_EXCEPT);feraiseexcept(FE_DIVBYZERO|FE_INVALID);return (fetestexcept(FE_ALL_EXCEPT)&(FE_DIVBYZERO|FE_INVALID))==(FE_DIVBYZERO|FE_INVALID)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){fenv_t saved;double one=1,zero=0;feclearexcept(FE_ALL_EXCEPT);feraiseexcept(FE_INVALID);feholdexcept(&saved);(void)(one/zero);feupdateenv(&saved);return (fetestexcept(FE_ALL_EXCEPT)&(FE_INVALID|FE_DIVBYZERO))==(FE_INVALID|FE_DIVBYZERO)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){_Atomic float a=20;feclearexcept(FE_ALL_EXCEPT);feraiseexcept(FE_DIVBYZERO);a+=22;return a==42&&fetestexcept(FE_DIVBYZERO)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){_Atomic float a=1;fesetround(FE_UPWARD);feclearexcept(FE_ALL_EXCEPT);float r=(a+=0x1p-24f);int raised=fetestexcept(FE_INEXACT);int mode=fegetround();fesetround(FE_TONEAREST);return a==0x1.000002p0f&&r==a&&raised&&mode==FE_UPWARD?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){_Atomic double a=40;feclearexcept(FE_ALL_EXCEPT);double x=a++,y=++a;return a==42&&x==40&&y==42&&!fetestexcept(FE_ALL_EXCEPT)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){_Atomic int a=40;feclearexcept(FE_ALL_EXCEPT);a+=2.5;return a==42&&fetestexcept(FE_INEXACT)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int calls;double rhs(void){++calls;feraiseexcept(FE_DIVBYZERO);return 22;}int main(void){_Atomic double a=20;feclearexcept(FE_ALL_EXCEPT);a+=rhs();return a==42&&calls==1&&fetestexcept(FE_DIVBYZERO)?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){double _Complex a=__builtin_complex(1.0,1.0),b=__builtin_complex(0x1p-53,0x1p-53);fesetround(FE_UPWARD);double _Complex up=a+b;fesetround(FE_DOWNWARD);double _Complex down=a+b;fesetround(FE_TONEAREST);return __real__ up>__real__ down&&__imag__ up>__imag__ down?42:1;}

#include <fenv.h>
#pragma STDC FENV_ACCESS ON
int main(void){_Atomic(float _Complex) a=__builtin_complex(1.0f,1.0f);fesetround(FE_UPWARD);feclearexcept(FE_ALL_EXCEPT);a+=__builtin_complex(0x1p-24f,0x1p-24f);float _Complex r=a;int raised=fetestexcept(FE_INEXACT);fesetround(FE_TONEAREST);return __real__ r==0x1.000002p0f&&__imag__ r==0x1.000002p0f&&raised?42:1;}
